def hidden_rule_fn(state):
    rows = len(state)
    cols = len(state[0])
    next_state = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            val = state[r][c]
            ne = state[(r - 1) % rows][(c + 1) % cols]
            nw = state[(r - 1) % rows][(c - 1) % cols]
            se = state[(r + 1) % rows][(c + 1) % cols]
            sw = state[(r + 1) % rows][(c - 1) % cols]
            diag = [ne, nw, se, sw]
            d_q = diag.count(2)
            if d_q == 0 or d_q == 2:
                next_state[r][c] = 0 if val == 0 else 1
            elif d_q == 1:
                next_state[r][c] = val + 1 if val < 2 else 1
            elif d_q == 3:
                next_state[r][c] = 2
            elif d_q == 4:
                next_state[r][c] = 0
    return next_state
